import json, sys
data = json.loads(json.loads(sys.stdin.read())['result'])
exps = data['data']['experiments']
# Count DONE experiments by category
categories = {
    'exec-only FOL': 0, 'ISR b01 FOL': 0, 'ISR b02 FOL': 0, 'ISR b03 FOL': 0,
    'random b01 FOL': 0, 'random b03 FOL': 0, 'SFT FOL': 0,
    'shuffled-ISR': 0, 'prolog': 0, 'prooffol': 0,
    '8B': 0, 'llama': 0, 'other': 0
}
for k, v in exps.items():
    if v.get('status') != 'DONE': continue
    if v.get('conclusion') in ('killed', 'failed'): continue
    kl = k.lower()
    if 'llama' in kl or 'd165' in kl or 'd158' in kl:
        categories['llama'] += 1
    elif '8b' in kl or 'd154' in kl:
        categories['8B'] += 1
    elif 'shuffled' in kl or 'd157' in kl:
        categories['shuffled-ISR'] += 1
    elif 'pf-' in kl or 'prooffol' in kl or 'd146' in kl:
        categories['prooffol'] += 1
    elif 'prolog' in kl:
        categories['prolog'] += 1
    elif 'sft' in kl:
        categories['SFT FOL'] += 1
    elif 'random' in kl and 'b01' in kl:
        categories['random b01 FOL'] += 1
    elif 'random' in kl and ('b03' in kl or 'b0.3' in kl):
        categories['random b03 FOL'] += 1
    elif 'exec' in kl and 'only' in kl:
        categories['exec-only FOL'] += 1
    elif 'b01' in kl or 'b0.1' in kl:
        categories['ISR b01 FOL'] += 1
    elif 'b02' in kl or 'b0.2' in kl:
        categories['ISR b02 FOL'] += 1
    elif 'b03' in kl or 'b0.3' in kl:
        categories['ISR b03 FOL'] += 1
    else:
        categories['other'] += 1
total = sum(categories.values())
print(f'Total non-killed DONE: {total}')
for cat, n in sorted(categories.items(), key=lambda x: -x[1]):
    if n > 0:
        print(f'  {cat}: {n}')
